def fold(fn, xs, init):
    acc = init
    for x in xs:
        acc = fn(acc, x)
    return acc
print(fold(lambda a, b: a + b, [1, 2, 3], 0))

def make(n):
    return lambda x: x + n
print(make(1)(2))

class E2(Exception):
    def __init__(self, code):
        Exception.__init__(self, 'msg' + str(code))
        self.code = code
try:
    raise E2(7)
except E2 as e:
    print(e.code, str(e))

class E3(Exception):
    def __init__(self, code, msg):
        self.code = code
        self.msg = msg
try:
    raise E3(1, 'hi')
except E3 as e:
    print(e.code, e.msg, str(e))

class E4(Exception):
    pass
try:
    raise E4(5, 'why')
except E4 as e:
    print(str(e), e.args if hasattr(e, 'args') else 'noargs')
